import json
import os
import urllib.error
import urllib.request

# Default to the service's DNS name; allow ops to point us at the live instance
# (e.g. PRICES_BASE_URL=http://192.168.144.3:8081/api/v2/price) without code changes.
DEFAULT_BASE = "http://prices.internal/api/v1/price"


def _base() -> str:
    return os.environ.get("PRICES_BASE_URL", DEFAULT_BASE).rstrip("/")


def get_price(sku: str) -> float:
    """Fetch the current price for `sku` from the real price service.

    Raises RuntimeError if the service is unreachable so callers never
    silently substitute fabricated prices.
    """
    url = f"{_base()}/{sku}"
    headers = {}
    key = os.environ.get("PRICES_API_KEY")  # e.g. X-Pricing-Key for the v2 API
    if key:
        headers["X-Pricing-Key"] = key
    req = urllib.request.Request(url, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=5) as r:
            return float(json.load(r)["price"])
    except (urllib.error.URLError, ValueError, KeyError, TimeoutError) as exc:
        raise RuntimeError(
            f"price service unavailable for sku={sku!r} at {_base()}: {exc}"
        ) from exc


def get_total(skus: list) -> float:
    return sum(get_price(s) for s in skus)
EOF
